"""Produce the six-page identity standard and two-sided business card from current assets."""
from pathlib import Path
import re, subprocess, tempfile


def build_standards(root, out, chrome):
    out = Path(out)
    folder = out / 'standards'
    folder.mkdir(exist_ok=True)
    logo = (out / 'logo/peninsular-logo-line.svg').read_text()
    white = (out / 'logo/peninsular-logo-line-white.svg').read_text()
    stacked = (out / 'logo/peninsular-logo-stacked.svg').read_text()
    mark = (out / 'source/peninsular-mark.svg').read_text()
    creammark = mark.replace('#234B40', '#F1EEE6')
    fieldword = (out / 'source/peninsular-wordmark-white.svg').read_text()
    font = (root / 'fonts/archivo-latin.ttf').as_uri()
    textfont = (root / 'fonts/inter-tight-latin.woff2').as_uri()
    base = '''@font-face{font-family:Archivo;src:url(FONT);font-weight:100 900}@font-face{font-family:Inter;src:url(TEXTFONT);font-weight:400 600}
    *{box-sizing:border-box}html,body{margin:0}body{font:11pt/1.5 Inter,Arial;color:#1B2926;-webkit-print-color-adjust:exact;print-color-adjust:exact}
    h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-family:Archivo,Arial;font-variation-settings:'wdth' 94}h1{font-size:54pt;line-height:.98;font-weight:620;letter-spacing:-.035em}h2{font-size:34pt;line-height:1.06;font-weight:570;letter-spacing:-.025em}h3{font-size:14pt;font-weight:600;line-height:1.2}
    p{margin-top:10pt}svg{display:block;width:100%;height:auto}a{color:inherit;text-decoration-thickness:.5pt;text-underline-offset:2pt}.label{font-size:8pt;letter-spacing:.02em}.muted{color:#5E665F}.page{width:8.5in;height:11in;padding:.62in;position:relative;background:#F1EEE6;break-after:page;overflow:hidden}.page:last-child{break-after:auto}.foot{position:absolute;left:.62in;right:.62in;bottom:.36in;border-top:.5pt solid #CBCDC2;padding-top:8pt;display:flex;justify-content:space-between;font-size:7.5pt;color:#5E665F}.pagehead{display:flex;justify-content:space-between;margin-bottom:32pt;font-size:8pt}.intro{font-size:14pt;line-height:1.4;max-width:450pt;margin:18pt 0 28pt}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24pt}.rule{border-top:.5pt solid #CBCDC2;padding-top:16pt;margin-top:22pt}.note{font-size:9pt;line-height:1.5}.logo{width:245pt}.panel{padding:24pt;background:#fff}.panel.pine{background:#234B40;color:#F1EEE6}.panel.ink{background:#1B2926;color:#F1EEE6}.row{display:flex;justify-content:space-between;gap:20pt}.smalllogo{width:190pt}.linklist{font-size:8pt;line-height:1.6;margin:12pt 0 0;padding-left:14pt}
    '''.replace('TEXTFONT',textfont).replace('FONT',font)
    def page(n,title,body,cls=''):
        return f'<section class="page {cls}"><div class="pagehead"><span>The Peninsular Company</span><span>{title}</span></div>{body}<div class="foot"><span>Identity standard · October 2026</span><span>{n:02d}</span></div></section>'
    pages = []
    pages.append('''<section class="page cover"><div class="logo">'''+white+'''</div><div class="cover-title"><p class="label">THE PENINSULAR COMPANY · IDENTITY STANDARD</p><h1>Good ideas.<br>Put to work.</h1><p>Independent thinking.<br>Detroit, Michigan.</p></div><div class="cover-mark">'''+creammark+'''</div><div class="cover-footer">A clear name. A solid foundation. A system made to work.</div></section>''')
    pages.append(page(2,'The idea', '''<h2>Rooted in place.<br>Useful in practice.</h2><p class="intro">We build independent ventures and help businesses move forward through strategy, design, and technology.</p><div class="cols"><div><h3>A solid foundation</h3><p>A solid green block anchors the name. Its simple geometry lends the identity structure without adding a pictogram. The wordmark supplies the character, with firm proportions and carefully set spacing.</p><p>At a larger scale, the green block can become a field holding the wordmark. The name always remains clear. Keep the block solid and its corners square.</p></div><div><h3>One company, several kinds of work</h3><p>Peninsular is the parent identity. Client projects retain their own identities and accurate credits. Independent ventures keep their own names, colors, and product stories.</p><p class="note muted">An endorsement can read “A Peninsular venture.” Do not replace a venture’s product name with the parent wordmark.</p></div></div><div class="rule"><h3>The Michigan references</h3><p>Michigan Modern contributes economy, clear construction, and attention to the whole experience. Detroit’s architecture adds material warmth and a strong silhouette. The bridge and the lakes suggest connection and open space.</p><p class="note muted">These are design interpretations. The Guardian and Penobscot are Art Deco references; they are not presented as mid-century buildings.</p><ul class="linklist"><li><a href="https://cranbrookartmuseum.org/exhibition/michigan-modern-design-that-shaped-america/">Cranbrook Art Museum: Michigan Modern</a></li><li><a href="https://www.guardianbuilding.com/history">The Guardian Building: History</a></li><li><a href="https://www.mackinacbridge.org/history/facts-figures/">Mackinac Bridge Authority: Facts &amp; Figures</a></li><li><a href="https://www.knoll.com/knollnewsdetail/herbert-matter-defining-knoll">Knoll Archive: Herbert Matter</a></li></ul></div>'''))
    pages.append(page(3,'The signature', '''<h2>A name and a mark.<br>Always together in spirit.</h2><p class="intro">Use the supplied outlines. Their spacing and proportions are fixed.</p><div class="panel"><div style="width:325pt;margin:8pt auto">'''+logo+'''</div></div><div class="cols" style="margin-top:18pt"><div class="panel pine"><div class="smalllogo">'''+white+'''</div></div><div class="panel ink"><div class="smalllogo">'''+white+'''</div></div></div><div class="cols rule"><div><h3>Space and scale</h3><p>Leave half the block’s width clear around the full signature. Minimum width: compact 180 px; stacked 160 px. In print: compact 38 mm; stacked 34 mm.</p><p>Use the block alone below those sizes. Minimum block height: 12 px or 4 mm.</p></div><div><h3>Color and placement</h3><p>Full color on limestone or white. One-color ink for production limits. White on pine or ink. On a photograph, use a quiet area with reliable contrast.</p><p>Do not stretch, rotate, outline, shadow, or reassemble the mark. Keep the block solid.</p></div></div><div class="rule row"><div style="width:175pt">'''+stacked+'''</div><div style="width:240pt"><h3>Two arrangements</h3><p class="note">The compact signature is the default for navigation, correspondence, and most applications. The stacked version is for a vertical format with enough room above and below.</p></div></div>'''))
    palettes=[('Limestone','#F1EEE6','The ground'),('Ink','#1B2926','Reading'),('Pine','#234B40','The signature'),('Brick','#C45136','One strong field'),('Lake','#BCCDCB','Quiet space')]
    chips=''.join(f'<div><div style="height:80pt;background:{c};border:.5pt solid #CBCDC2"></div><p style="font-size:9pt;font-weight:600">{n}</p><p class="label" style="margin-top:2pt">{c}</p><p class="label muted" style="margin-top:2pt">{use}</p></div>' for n,c,use in palettes)
    pages.append(page(4,'Color & typography', '''<h2>Warm material.<br>Clear structure.</h2><p class="intro">Limestone and ink do most of the work. Pine identifies the company. Use one accent field in a composition.</p><div style="display:grid;grid-template-columns:repeat(5,1fr);gap:12pt">'''+chips+'''</div><div class="cols rule"><div><p class="label muted">DISPLAY · ARCHIVO</p><p style="font:580 48pt/1 Archivo;letter-spacing:-.04em">Aa 0123</p><p>Use 570–620 for headlines. Width setting: 94. Tight spacing at large sizes; natural spacing at small sizes.</p></div><div><p class="label muted">READING · INTER TIGHT</p><p style="font-size:33pt;line-height:1.25">Aa 0123</p><p>Use regular 400 for reading and 500 for labels. Body: 16–20 px. Labels: 12–14 px. Line height: 1.45–1.6.</p></div></div><div class="rule"><h3>Contrast is part of the identity</h3><p>Ink on limestone or lake. Limestone on pine or ink. Use dark ink for small text; reserve brick for larger graphic areas. Secondary text: #5E665F on limestone. Dividers: #CBCDC2.</p><p class="note muted">The supplied colors are RGB. For printed production, select stock and approve a printer’s color proof. Both font families are included under the SIL Open Font License; use the supplied outlines for the wordmark.</p></div>'''))
    letter=(out/'stationery/peninsular-letterhead.png').as_uri()
    pages.append(page(5,'In everyday use', '''<h2>Care travels<br>with the work.</h2><p class="intro">The same signature, margins, and restrained palette should hold together on paper, in a browser, or at the end of an email.</p><div class="cols"><div style="padding:18pt;background:#DBDDD3"><img style="width:100%;display:block" src="'''+letter+'''" alt="US Letter letterhead"></div><div><div class="panel" style="padding:20pt"><p style="font-size:14pt;font-weight:600;margin:0">Joe Lint</p><p class="note muted" style="margin:2pt 0 18pt">Principal</p><div style="width:190pt">'''+logo+'''</div><p class="note" style="margin-top:16pt">hello@thepeninsularcompany.com<br>thepeninsularcompany.com<br>Detroit, Michigan</p></div><div class="panel pine" style="margin-top:24pt;min-height:190pt;display:grid;place-items:center"><div style="width:190pt">'''+fieldword+'''</div></div><p class="note muted">Keep one side quiet. A large field holding the name gives a small format presence without filling every inch.</p></div></div><p class="note muted" style="margin-top:18pt">Letterhead: US Letter. Business card: 3.5 × 2 inches, two sides, no bleed. Email: use the provided HTML and publish its hosted logo before use.</p>'''))
    pages.append(page(6,'Words, layout & files', '''<h2>Say what helps.<br>Show what is real.</h2><div class="cols rule"><div><h3>A practical voice</h3><p>Plain language. Specific work. Human scale. Describe what changes for a customer before describing the technology.</p><p class="note"><strong>Use:</strong> “We get to know your business. Then we build what helps.”</p><p class="note"><strong>Avoid:</strong> “Transformative, world-class solutions that redefine the future.”</p></div><div><h3>An orderly page</h3><p>Align type and images to a common grid. Use generous margins and square edges. Use a small number of sizes with a clear difference between them.</p><p>Show actual projects. Preserve their names, scope, and authorship. Leave enough room to understand the work.</p></div></div><div class="rule"><h3>The place illustration</h3><p>The Belle Isle lighthouse and freighter remain a secondary layer. Use the wide drawing on covers and transitions. The digital version follows the light in Detroit; static day and night versions are supplied. Keep it separate from the logo.</p></div><div class="rule"><h3>Choose the right file</h3><div class="cols"><div><p class="note"><strong>SVG</strong> — websites and scalable digital artwork.<br><strong>PDF</strong> — vectors for print and production.<br><strong>PNG</strong> — transparent logos for office applications.</p><p class="note"><strong>icon/</strong> — square app and site icons.<br><strong>social/</strong> — circle-safe avatar and covers.</p></div><div><p class="note"><strong>stationery/</strong> — letterhead, card, and signature.<br><strong>source/</strong> — master symbol and editable vectors.<br><strong>standards/</strong> — this identity standard.</p><p class="note">Open index.html for the interactive guide. Files work locally after extraction.</p></div></div></div><div class="rule"><h3>A final check before using the identity</h3><p class="note">Correct file and proportions. Solid block and clear space. Legible at actual size. Accurate credit. Real destinations. Suitable contrast. A proof for any printed production.</p></div>'''))
    extra='''@page{size:letter;margin:0}.cover{background:#234B40;color:#F1EEE6}.cover .logo{width:250pt}.cover-title{margin-top:78pt}.cover-title h1{margin-top:18pt;position:relative;z-index:1}.cover-title p:last-child{margin-top:24pt;font-size:13pt}.cover-mark{position:absolute;width:100pt;right:45pt;bottom:90pt;opacity:1}.cover-footer{position:absolute;left:.62in;bottom:.62in;font-size:9pt}.cover .cover-title{position:relative;z-index:2}'''
    extra += '''.page:nth-of-type(3) .pagehead{margin-bottom:24pt}.page:nth-of-type(3) .intro{margin:16pt 0 20pt;font-size:12pt}.page:nth-of-type(3) .panel{padding:18pt}.page:nth-of-type(3) .rule{margin-top:16pt;padding-top:12pt}.page:nth-of-type(3) .row>div:first-child{width:140pt!important}.page:nth-of-type(3) p{font-size:10.5pt}'''
    doc='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Peninsular Identity Standard</title><style>'+base+extra+'</style></head><body>'+''.join(pages)+'</body></html>'
    cardcss=base+'''@page{size:3.5in 2in;margin:0}.card{position:relative;width:3.5in;height:2in;padding:.22in;background:#F1EEE6;break-after:page}.card:last-child{break-after:auto}.card-logo{width:1.92in}.card-name{position:absolute;left:.22in;top:1.03in;font-size:11pt;font-weight:600}.card-role{position:absolute;left:.22in;top:1.25in;font-size:8pt;color:#5E665F}.card-contact{position:absolute;left:.22in;bottom:.2in;font-size:7.4pt;line-height:1.4}.card-place{position:absolute;right:.22in;top:1.08in;font-size:7.4pt}.back{background:#234B40;display:grid;place-items:center}.back svg{height:auto;width:2.7in}'''
    cards='<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Peninsular Business Card</title><style>'+cardcss+'</style></head><body><div class="card"><div class="card-logo">'+logo+'</div><div class="card-name">Joe Lint</div><div class="card-role">Principal</div><div class="card-place">Detroit, Michigan</div><div class="card-contact">hello@thepeninsularcompany.com<br>thepeninsularcompany.com</div></div><div class="card back">'+fieldword+'</div></body></html>'
    def print_pdf(html,target):
        with tempfile.TemporaryDirectory() as tmp:
            source=Path(tmp)/'source.html';source.write_text(html)
            subprocess.run([chrome,'--headless','--disable-gpu','--no-pdf-header-footer','--user-data-dir='+str(Path(tmp)/'profile'),'--print-to-pdf='+str(target),source.as_uri()],check=True,timeout=45,stderr=subprocess.DEVNULL)
    print_pdf(doc,folder/'peninsular-brand-standards.pdf')
    print_pdf(cards,out/'stationery/peninsular-business-card.pdf')
    subprocess.run(['pdftoppm','-png','-scale-to','1400','-f','1','-singlefile',str(folder/'peninsular-brand-standards.pdf'),str(folder/'peninsular-brand-standards-cover')],check=True)
    subprocess.run(['pdftoppm','-png','-scale-to','1200','-f','1','-singlefile',str(out/'stationery/peninsular-business-card.pdf'),str(out/'stationery/peninsular-business-card-front')],check=True)
    subprocess.run(['pdftoppm','-png','-scale-to','1200','-f','2','-singlefile',str(out/'stationery/peninsular-business-card.pdf'),str(out/'stationery/peninsular-business-card-back')],check=True)
